cd /c/sheep
g(){ node tools/gen.mjs "$@" > /dev/null 2>&1 && echo "done $2" || echo "FAIL $2"; }
g --out art/raw/world/near.png --aspect 1536x1024 --bg transparent --quality high --n 3 --ref ref/2b740dbd-0be0-42e5-92bb-1abc9aef6bc9.png --ref ref/c0f6f4b1-4af2-410f-838a-9f2d25a3fa36.png --prompt "16-bit SNES-era pixel art game layer, same palette and rendering style as the reference game screenshots (Contra / Metal Slug style jungle stage), crisp chunky pixels, dark outlines, no text, no UI, no characters. Draw ONLY one massive close-up jungle rock cliff mass (a single set piece) on a fully transparent background: a huge tall block of dark brown-grey layered rock with deep shadows and strong contrast, thick bright moss and jungle overgrowth on its flat top and ledges, long hanging vines down its face, and a powerful white-and-blue waterfall pouring from a notch near the top all the way down its face into white foaming spray at the bottom. Saturated rich colours, close to the viewer, like the big cliffs right behind the player in the reference screenshots. The rock fills the whole height of the image, its flat mossy top in the upper part leaving some empty transparent space above it; the sides are irregular. Nothing else." &
g --out art/raw/world/near2.png --aspect 1536x1024 --bg transparent --quality high --n 2 --ref ref/2b740dbd-0be0-42e5-92bb-1abc9aef6bc9.png --ref ref/369c595b-d6f6-4f08-9cbb-a2729370ed58.png --prompt "16-bit SNES-era pixel art game layer, same palette and rendering style as the reference game screenshots (Contra / Metal Slug style jungle stage), crisp chunky pixels, dark outlines, no text, no UI, no characters. Draw ONLY one massive close-up jungle rock pillar plateau (a single set piece) on a fully transparent background: a tall broad column of dark mossy boulder rock with deep shadows, strong contrast, jungle ferns and a couple of palm trees growing on its flat top, curtains of hanging vines on its face, and two thin waterfalls streaming down the side into white spray at the bottom. Saturated rich colours, close to the viewer. The rock fills the whole height of the image except empty transparent space above the top. Nothing else." &
